import type { ComponentProps, ReactNode } from "react"

import { cn } from "@humanctl/ui/lib/cn"

type AppShellProps = ComponentProps<"div"> & {
  navigation?: ReactNode
  topbar?: ReactNode
  detail?: ReactNode
  statusbar?: ReactNode
}

function AppShell({
  className,
  navigation,
  topbar,
  detail,
  statusbar,
  children,
  ...props
}: AppShellProps) {
  return (
    <div
      data-slot="app-shell"
      className={cn(
        "grid h-dvh min-h-0 w-full overflow-hidden bg-background text-ink max-[960px]:grid-cols-[minmax(0,1fr)]",
        navigation
          ? "grid-cols-[var(--rail)_minmax(0,1fr)]"
          : "grid-cols-[minmax(0,1fr)]",
        className,
      )}
      {...props}
    >
      {navigation ? (
        <nav
          data-slot="app-navigation"
          aria-label="Primary"
          className="min-h-0 border-r border-border bg-surface pt-[var(--chrome)] max-[960px]:hidden"
        >
          {navigation}
        </nav>
      ) : null}
      <div data-slot="app-stage" className="flex min-h-0 min-w-0 flex-col">
        <div data-slot="app-upper" className="flex min-h-0 min-w-0 flex-1">
          <div data-slot="app-workspace" className="flex min-h-0 min-w-0 flex-1 flex-col">
            {topbar ? (
              <header
                data-slot="app-topbar"
                className={cn(
                  "flex h-[var(--chrome)] shrink-0 items-center border-b border-border bg-background px-3 max-[960px]:pl-[var(--traffic-light-inset)]",
                  !navigation && "pl-[var(--traffic-light-inset)]",
                )}
              >
                {topbar}
              </header>
            ) : null}
            <main data-slot="app-main" className="min-h-0 min-w-0 flex-1 overflow-hidden">
              {children}
            </main>
          </div>
          {detail ? (
            <aside
              data-slot="app-detail"
              className="min-h-0 w-[var(--detail)] shrink-0 border-l border-border bg-background max-[1040px]:hidden"
            >
              {detail}
            </aside>
          ) : null}
        </div>
        {statusbar ? (
          <footer
            data-slot="app-statusbar"
            aria-label="Fleet status"
            className="flex h-[var(--status-band)] shrink-0 items-center border-t border-border bg-surface px-3"
          >
            {statusbar}
          </footer>
        ) : null}
      </div>
    </div>
  )
}

export { AppShell, type AppShellProps }

import type { ComponentProps } from "react"

import { cn } from "@humanctl/ui/lib/cn"

function PageFrame({ className, ...props }: ComponentProps<"section">) {
  return (
    <section
      data-slot="page-frame"
      className={cn("flex h-full min-h-0 min-w-0 flex-col bg-background", className)}
      {...props}
    />
  )
}

function PageHeader({ className, ...props }: ComponentProps<"header">) {
  return (
    <header
      data-slot="page-header"
      className={cn("flex min-h-[var(--row-decision)] shrink-0 items-center gap-4 border-b border-border px-4 py-2", className)}
      {...props}
    />
  )
}

function PageHeading({ className, ...props }: ComponentProps<"div">) {
  return <div className={cn("min-w-0 flex-1", className)} {...props} />
}

function PageTitle({ className, ...props }: ComponentProps<"h1">) {
  return <h1 className={cn("truncate text-[16px] leading-5 font-semibold text-ink", className)} {...props} />
}

function PageDescription({ className, ...props }: ComponentProps<"p">) {
  return <p className={cn("mt-0.5 truncate text-[13px] leading-5 text-ink-3", className)} {...props} />
}

function PageActions({ className, ...props }: ComponentProps<"div">) {
  return <div className={cn("ml-auto flex shrink-0 items-center gap-1.5", className)} {...props} />
}

function PageBody({ className, ...props }: ComponentProps<"div">) {
  return <div className={cn("min-h-0 flex-1 overflow-hidden", className)} {...props} />
}

export { PageActions, PageBody, PageDescription, PageFrame, PageHeader, PageHeading, PageTitle }
